import{_ as d,o as a,c as r,a6 as e}from"./chunks/framework.B_q3ZJNF.js";const u=JSON.parse('{"title":"A股交易规则与费用速查表","description":"","frontmatter":{"title":"A股交易规则与费用速查表"},"headers":[],"relativePath":"a-share-investing-course/trading-rules-cheatsheet.md","filePath":"a-share-investing-course/docs/trading-rules-cheatsheet.md"}'),h={name:"a-share-investing-course/trading-rules-cheatsheet.md"};function l(o,t,i,b,n,s){return a(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="a股交易规则与费用速查表" tabindex="-1">A股交易规则与费用速查表 <a class="header-anchor" href="#a股交易规则与费用速查表" aria-label="Permalink to &quot;A股交易规则与费用速查表&quot;">​</a></h1><blockquote><p>「截至写作时口径，以交易所最新规则为准——修订年份见第 2 章」</p><p>本表为教学速查，不构成投资建议。<strong>投资有风险，入市需谨慎</strong>；只用闲钱投资，不要借贷、不要动用生活必需资金。</p></blockquote><p>本表汇总第 2 章《一笔订单的旅程》正文已核实的规则与费用口径：每个数字都能在第 2 章正文找到出处，正文没有的项目本表不列。交易时段以沪深主板为例。</p><h2 id="零、开户与资金" tabindex="-1">零、开户与资金 <a class="header-anchor" href="#零、开户与资金" aria-label="Permalink to &quot;零、开户与资金&quot;">​</a></h2><table tabindex="0"><thead><tr><th>事项</th><th>要点</th></tr></thead><tbody><tr><td>在哪开户</td><td>只在持牌证券公司（券商）开户：证监会官网公示的证券公司名录可查；开户在券商官方 App 线上办理，需身份证与银行卡</td></tr><tr><td>适当性</td><td>开户时会做风险测评；创业板、科创板等板块另有交易经验与资金门槛，不满足就先不开</td></tr><tr><td>资金纪律</td><td>入市的钱限于亏光了也不影响生活的闲钱；不借贷、不加杠杆、不动生活费——第 20 章的破产概率算术对谁都一视同仁</td></tr></tbody></table><h2 id="一、交易时段-沪深主板" tabindex="-1">一、交易时段（沪深主板） <a class="header-anchor" href="#一、交易时段-沪深主板" aria-label="Permalink to &quot;一、交易时段（沪深主板）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>时段</th><th>阶段</th><th>规则要点</th></tr></thead><tbody><tr><td>9:15–9:20</td><td>开盘集合竞价·收单</td><td>可挂单、可撤单（价格允许虚晃）</td></tr><tr><td>9:20–9:25</td><td>开盘集合竞价·锁单</td><td>只可挂单、不可撤单——报出去就锁死，防的就是挂天量高价单引人追涨、再悄悄撤掉的虚晃</td></tr><tr><td>9:25</td><td>撮合</td><td>按最大成交量原则算出开盘价，全部申报按这一个价格一次性撮合</td></tr><tr><td>9:25–9:30</td><td>只收单不处理</td><td>未成交的申报自动转入 9:30 开始的连续竞价</td></tr><tr><td>9:30 起</td><td>连续竞价</td><td>来一张单、处理一张，全天持续撮合</td></tr><tr><td>14:57–15:00</td><td>收盘集合竞价</td><td>用与开盘同样的办法（最大成交量原则）定收盘价</td></tr></tbody></table><p>配套两则：</p><table tabindex="0"><thead><tr><th>规则</th><th>内容</th></tr></thead><tbody><tr><td>T+1 交收</td><td>当天买入的股票最快下一个交易日才能卖出；卖出所得资金当天可继续买股票，转出银行卡通常要到下一交易日（自 1995 年起施行）</td></tr><tr><td>申报当日有效</td><td>未成交的申报当日有效，收盘自动作废；次日集合竞价重新挂单、重新排队</td></tr></tbody></table><h2 id="二、涨跌幅限制" tabindex="-1">二、涨跌幅限制 <a class="header-anchor" href="#二、涨跌幅限制" aria-label="Permalink to &quot;二、涨跌幅限制&quot;">​</a></h2><table tabindex="0"><thead><tr><th>板块 / 情形</th><th>幅度</th><th>说明</th></tr></thead><tbody><tr><td>主板</td><td>±10%</td><td>1996 年 12 月之前A股没有涨跌停</td></tr><tr><td>主板 ST 股票</td><td>±10%</td><td>2026 年 7 月起与主板普通股一致；此前十多年一直是更窄的 ±5%</td></tr><tr><td>创业板 / 科创板</td><td>±20%</td><td>—</td></tr><tr><td>北交所</td><td>±30%</td><td>—</td></tr><tr><td>新股上市首日等特殊情形</td><td>另有规定</td><td>以交易所最新规则为准</td></tr></tbody></table><p>边界算法：昨收盘 ×（1 ± 幅度）→ 四舍五入到分。例（主板，昨收 9.87 元）：涨停 9.87 × 1.1 = 10.857 → 10.86 元；跌停 9.87 × 0.9 = 8.883 → 8.88 元。申报价高于涨停价或低于跌停价，直接是无效申报（废单），系统拒收。</p><h2 id="三、申报单位" tabindex="-1">三、申报单位 <a class="header-anchor" href="#三、申报单位" aria-label="Permalink to &quot;三、申报单位&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>规则</th></tr></thead><tbody><tr><td>手</td><td>A股的买卖单位，1 手 = 100 股</td></tr><tr><td>买入</td><td>必须挂整手，即 100 股的整数倍</td></tr><tr><td>卖出</td><td>可以有零股：分红送股凑出来的零头，卖出时允许一次带出</td></tr><tr><td>盘口数量单位</td><td>手（买一 89 手 = 8,900 股买单）</td></tr></tbody></table><h2 id="四、交易费用三件套" tabindex="-1">四、交易费用三件套 <a class="header-anchor" href="#四、交易费用三件套" aria-label="Permalink to &quot;四、交易费用三件套&quot;">​</a></h2><table tabindex="0"><thead><tr><th>费用</th><th>方向</th><th>口径</th><th>提醒</th></tr></thead><tbody><tr><td>印花税</td><td>卖出单向，买入不收</td><td>成交金额的 0.05%</td><td>2023 年 8 月起减半至此税率，以最新公告为准</td></tr><tr><td>佣金</td><td>买卖双向</td><td>常见万 1 到万 3；单笔不足 5 元按 5 元收</td><td>以你的券商合同为准</td></tr><tr><td>过户费等小项</td><td>双向</td><td>按成交金额十万分之一量级</td><td>量级参考，以登记结算与券商口径为准；金额小到不影响第 2 章的算账，该章算例一律忽略</td></tr></tbody></table><p>两个咬人的细节（第 2 章算过）：</p><ul><li>最低佣金线：万 2.5 的名义费率下，单笔成交 2 万元佣金恰好 5 元；成交额低于 2 万元的每一笔，实际费率都被 5 元顶高——5,000 元的单实付佣金 5 元 = 0.1%，是名义费率的 4 倍。</li><li>回本涨幅：第 2 章算例（10.00 元买入 500 股、若干交易日后 11.00 元全部卖出，佣金万 2.5 最低 5 元），费用吃掉 12.75 元，约占买入成本 0.25%——股价要先涨过这道坎，才刚回到起点。</li></ul><h2 id="五、竞价与撮合" tabindex="-1">五、竞价与撮合 <a class="header-anchor" href="#五、竞价与撮合" aria-label="Permalink to &quot;五、竞价与撮合&quot;">​</a></h2><table tabindex="0"><thead><tr><th>规则</th><th>内容</th></tr></thead><tbody><tr><td>价格优先时间优先</td><td>买单出价更高者优先成交，卖单要价更低者优先成交；价格相同，先申报的排前面。主机只看价格和时间，不看你是谁、单子多大</td></tr><tr><td>集合竞价·最大成交量原则</td><td>逐个候选价计算：出价不低于它的买单共多少股、要价不高于它的卖单共多少股，两边取小为该价可成交量；可成交量最大的价格定为开盘价，全部成交按该价格结算</td></tr><tr><td>成交分配</td><td>出价高于开盘价的买单全部成交，要价低于开盘价的卖单全部成交，恰好等于开盘价的按先来后到尽量成交</td></tr><tr><td>可成交量并列最大</td><td>沪深口径分叉——沪市先取未成交量更小的价格、仍并列取中间价；深市直接取更接近昨收盘价的（细则以各交易所最新规则为准）</td></tr><tr><td>吃单的成交价</td><td>出价直接跨过对手价、主动立刻成交；成交价按先在队伍里的那一方（对手档位）的价格，不是你挂的价格</td></tr><tr><td>跌停价上的队</td><td>所有卖单挤在跌停价同一价格上，价格优先失效，只剩时间优先；报出低于跌停价的价格直接废单。同价的队伍里先来后到就是一切：撤单重挂，等于亲手把位置让出去</td></tr></tbody></table><h2 id="六、盘口五档" tabindex="-1">六、盘口五档 <a class="header-anchor" href="#六、盘口五档" aria-label="Permalink to &quot;六、盘口五档&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>含义</th></tr></thead><tbody><tr><td>盘口五档（order book）</td><td>买卖双方报价的实时排队表：买方出价从高到低排五档（买一~买五）、卖方要价从低到高排五档（卖一~卖五），中间的空隙是价差；买一卖一是离成交最近的那一档，两者之差叫价差，各档数量的单位是手</td></tr></tbody></table><h2 id="七、风险警示-st-与-st" tabindex="-1">七、风险警示：ST 与 *ST <a class="header-anchor" href="#七、风险警示-st-与-st" aria-label="Permalink to &quot;七、风险警示：ST 与 *ST&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td>ST 含义</td><td>被交易所贴上「特别处理」风险警示标签的股票（ST 是 Special Treatment 的缩写），多半是财务状况或规范运作出了问题</td></tr><tr><td>*ST 含义</td><td>第 19 章开篇案例中的戴帽情形：公司连续两年亏损、年报被审计师出具无法表示意见，股票戴帽 *ST（具体认定标准以交易所最新规则为准）</td></tr><tr><td>涨跌幅变化</td><td>2026 年 7 月起，主板 ST 股票涨跌幅与普通股一致为 ±10%；此前十多年一直是更窄的 ±5%（第 2 章、第 19 章口径一致）</td></tr><tr><td>风险所在</td><td>警示标签本身才是风险：被贴牌的公司多半基本面已出问题，一旦利空兑现，连续一字跌停、想卖卖不掉的情形在 ST 股上并不罕见；涨跌幅改宽到 ±10% 后，单日能跌掉的幅度反而更大了</td></tr><tr><td>课程执行口径</td><td>第 19 章：戴帽 ST 直接不碰</td></tr></tbody></table><h2 id="八、分红与除权除息-一眼版" tabindex="-1">八、分红与除权除息（一眼版） <a class="header-anchor" href="#八、分红与除权除息-一眼版" aria-label="Permalink to &quot;八、分红与除权除息（一眼版）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>事项</th><th>要点</th></tr></thead><tbody><tr><td>除权除息是什么</td><td>分红送股后，交易所把股价按比例调低、把你的账户补上现金或股票，总资产不变——不是暴跌，也不是白送</td></tr><tr><td>10 送 10 例</td><td>10 元股票 10 送 10（每 10 股送 10 股），除权日股价直接标为 5 元、股数翻倍；账户总值没变</td></tr><tr><td>为什么必须开前复权</td><td>不复权的图上，除权日会留一道「假跳空」，伪造峰谷、死叉与形态——看图一律开前复权（第 11 章专讲）</td></tr><tr><td>股息率</td><td>近 12 个月每股分红 ÷ 现股价；长期投资者的重要读数，本课程技术流主线只做提醒，不展开</td></tr></tbody></table><h2 id="权威文档清单" tabindex="-1">权威文档清单 <a class="header-anchor" href="#权威文档清单" aria-label="Permalink to &quot;权威文档清单&quot;">​</a></h2><p>以下为课程 bible 记录的权威文档出处（规则会修订，以官方最新发布为准；链接为明文 URL，非站内跳转）：</p><ul><li>上海证券交易所交易规则（竞价、涨跌幅、申报单位）——上交所官网「规则」栏目：www.sse.com.cn</li><li>深圳证券交易所交易规则——深交所官网「规则」栏目：www.szse.cn</li><li>北京证券交易所股票交易规则——北交所官网：www.bse.cn</li><li>证监会投资者保护局 / 投资者教育基地（开户、适当性、风险警示）：www.csrc.gov.cn</li><li>财政部 / 税务总局关于证券交易印花税减半征收的公告（2023 年 8 月起卖出 0.05%）</li><li>沪深交易所收费表（佣金上限、经手费、过户费）</li></ul><p>注：交易规则会修订。本表与正文凡断言具体数字（涨跌幅、费率、竞价时段），均为截至写作时的口径，以交易所最新规则为准。</p>',30)])])}const p=d(h,[["render",l]]);export{u as __pageData,p as default};
